const input = require("fs").readFileSync(0, "utf8");
const [first, ...queries] = input.trim().split("\n");

class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  longestWordPrefix(word) {
    let node = this.root;
    let best = 0;
    for (let i = 0; i < word.length; i++) {
      if (!node.children.has(word[i])) {
        break;
      }
      node = node.children.get(word[i]);
      if (node.isEnd) {
        best = i + 1;
      }
    }
    return best === 0 ? null : word.slice(0, best);
  }
}

const trie = new Trie();
for (const word of first.trim().split(/\s+/)) {
  trie.insert(word);
}

for (const q of queries) {
  const text = q.trim();
  console.log(`${text}: ${trie.longestWordPrefix(text) ?? "none"}`);
}

