const input = require("fs").readFileSync(0, "utf8");
const [first, typedLine] = input.trim().split("\n");
const typed = typedLine.trim();

class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  find(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) {
        return null;
      }
      node = node.children.get(ch);
    }
    return node;
  }
}

function suggest(node, word, out) {
  if (out.length === 3) {
    return;
  }
  if (node.isEnd) {
    out.push(word);
  }
  for (const ch of [...node.children.keys()].sort()) {
    suggest(node.children.get(ch), word + ch, out);
  }
}

const trie = new Trie();
for (const word of first.trim().split(/\s+/)) {
  trie.insert(word);
}
for (let i = 1; i <= typed.length; i++) {
  const prefix = typed.slice(0, i);
  const out = [];
  const node = trie.find(prefix);
  if (node !== null) {
    suggest(node, prefix, out);
  }
  console.log(`${prefix}: ${out.length > 0 ? out.join(" ") : "-"}`);
}
